import React, { useState, useEffect, useRef } from 'react';
import chatBgImg from '../../assets/nen_khung_chat.jpg'; 

const NhanTin = () => {
    const [tabActive, setTabActive] = useState('all');
    const [selectedRooms, setSelectedRooms] = useState([]);
    const [message, setMessage] = useState('');
    const currentUser = "AD"; 

    const [chatHistory, setChatHistory] = useState(() => {
        const savedChat = localStorage.getItem('chatHistory');
        return savedChat ? JSON.parse(savedChat) : [];
    });

    const chatEndRef = useRef(null);

    const scrollToBottom = () => {
        chatEndRef.current?.scrollIntoView({ behavior: "smooth" });
    };

    useEffect(() => {
        localStorage.setItem('chatHistory', JSON.stringify(chatHistory));
        scrollToBottom();
    }, [chatHistory, tabActive]);

    const allRooms = [];
    for (let floor = 1; floor <= 9; floor++) {
        for (let num = 1; num <= 5; num++) {
            allRooms.push(`${floor}0${num}`);
        }
    }

    const toggleRoom = (roomId) => {
        if (selectedRooms.includes(roomId)) {
            setSelectedRooms(selectedRooms.filter(id => id !== roomId));
        } else {
            setSelectedRooms([...selectedRooms, roomId]);
        }
    };

    const handleSendMessage = (type) => {
        if (message.trim() === '') return;

        const newMessage = {
            id: Date.now(),
            sender: currentUser,
            content: message,
            type: type, 
            target: type === 'all' ? 'Tất cả' : selectedRooms.join(', '),
            time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
            fullTimestamp: new Date().toISOString()
        };

        setChatHistory([...chatHistory, newMessage]);
        setMessage('');
    };

    const canSendPrivate = selectedRooms.length > 0 && message.trim() !== '';

    const renderMessageList = (type) => {
        const filteredChats = chatHistory.filter(m => m.type === type);

        return filteredChats.map((msg, index) => {
            const isMe = msg.sender === currentUser;
            const prevMsg = filteredChats[index - 1];
            const isSameSenderAsPrev = prevMsg && prevMsg.sender === msg.sender;

            return (
                <div key={msg.id} style={{ 
                    display: 'flex', 
                    flexDirection: 'column',
                    alignItems: isMe ? 'flex-end' : 'flex-start',
                    marginBottom: isSameSenderAsPrev ? '4px' : '20px', // Tăng khoảng cách giữa các nhóm tin
                    marginTop: isSameSenderAsPrev ? '0px' : '10px'
                }}>
                    <div style={{ 
                        display: 'flex', 
                        flexDirection: isMe ? 'row-reverse' : 'row', 
                        alignItems: 'flex-end',
                        gap: '12px', // Tăng khoảng cách avatar và tin nhắn
                        maxWidth: '85%'
                    }}>
                        <div style={{ width: '40px', flexShrink: 0 }}> {/* Avatar lớn hơn chút */}
                            {!isSameSenderAsPrev && (
                                <div style={{ 
                                    width: '40px', height: '40px', borderRadius: '50%', 
                                    backgroundColor: isMe ? '#333' : '#111', color: '#fff', 
                                    display: 'flex', alignItems: 'center', justifyContent: 'center', 
                                    fontSize: '12px', fontWeight: 'bold', border: '2px solid rgba(255,255,255,0.3)'
                                }}>
                                    {msg.sender}
                                </div>
                            )}
                        </div>

                        <div style={{ 
                            backgroundColor: isMe ? 'rgba(30, 30, 30, 0.95)' : 'rgba(255, 255, 255, 1)', 
                            padding: '14px 20px', // Padding rộng hơn
                            borderRadius: isMe 
                                ? (isSameSenderAsPrev ? '22px 6px 22px 22px' : '22px 22px 6px 22px') 
                                : (isSameSenderAsPrev ? '6px 22px 22px 22px' : '22px 22px 22px 6px'), 
                            fontSize: '16px', // Tăng từ 13px lên 16px (Dễ đọc hơn rất nhiều)
                            lineHeight: '1.5', // Giãn dòng 1.5 cho thoáng
                            color: isMe ? '#fff' : '#000', // Màu chữ đậm hơn
                            boxShadow: '0 3px 10px rgba(0,0,0,0.15)',
                            border: isMe ? '1px solid rgba(255,255,255,0.1)' : 'none',
                            wordBreak: 'break-word'
                        }}>
                            {type === 'private' && isMe && !isSameSenderAsPrev && (
                                <div style={{ fontSize: '11px', fontWeight: 'bold', color: '#999', borderBottom: '1px solid rgba(255,255,255,0.1)', marginBottom: '8px', paddingBottom: '4px' }}>
                                    Gửi tới: {msg.target}
                                </div>
                            )}
                            {msg.content}
                            {!isSameSenderAsPrev && (
                                <div style={{ fontSize: '10px', opacity: 0.6, marginTop: '8px', textAlign: isMe ? 'right' : 'left' }}>
                                    {msg.time}
                                </div>
                            )}
                        </div>
                    </div>
                </div>
            );
        });
    };

    return (
        <div style={{
            flex: 1, display: 'flex', flexDirection: 'column', 
            backgroundImage: `url(${chatBgImg})`, backgroundSize: 'cover', backgroundPosition: 'center', 
            borderRadius: '30px', overflow: 'hidden', height: 'calc(100vh - 120px)', minHeight: 0,
            boxShadow: '0 10px 40px rgba(0,0,0,0.4)'
        }} className="glass-card">

            {/* Header Tabs */}
            <div style={{ padding: '25px', display: 'flex', gap: '20px', flexShrink: 0, background: 'rgba(0,0,0,0.3)' }}>
                <button onClick={() => setTabActive('all')} style={{ padding: '12px 30px', borderRadius: '25px', border: 'none', fontSize: '15px', fontWeight: 'bold', backgroundColor: tabActive === 'all' ? '#fff' : 'rgba(255,255,255,0.2)', color: tabActive === 'all' ? '#333' : '#fff', cursor: 'pointer', transition: '0.3s' }}>
                    Nhắn tin chung
                </button>
                <button onClick={() => setTabActive('private')} style={{ padding: '12px 30px', borderRadius: '25px', border: 'none', fontSize: '15px', fontWeight: 'bold', backgroundColor: tabActive === 'private' ? '#8b5e5e' : 'rgba(255,255,255,0.2)', color: '#fff', cursor: 'pointer', transition: '0.3s' }}>
                    Nhắn tin riêng
                </button>
            </div>

            {/* Main Chat Area */}
            <div style={{ flex: 1, padding: '25px', display: 'flex', overflow: 'hidden', minHeight: 0 }}>
                {tabActive === 'all' ? (
                    <div style={{ flex: 1, display: 'flex', flexDirection: 'column', minHeight: 0 }}>
                        <div style={{ flex: 1, overflowY: 'auto', paddingRight: '15px' }} className="custom-scrollbar">
                            {renderMessageList('all')}
                            <div ref={chatEndRef} />
                        </div>

                        <div style={{ display: 'flex', gap: '15px', paddingTop: '20px', flexShrink: 0 }}>
                            <input style={{ flex: 1, padding: '18px 25px', borderRadius: '30px', border: 'none', outline: 'none', fontSize: '16px', backgroundColor: 'rgba(255,255,255,1)', boxShadow: '0 4px 15px rgba(0,0,0,0.2)' }} placeholder="Nhập tin nhắn chung..." value={message} onChange={(e) => setMessage(e.target.value)} onKeyPress={(e) => e.key === 'Enter' && handleSendMessage('all')} />
                            <button onClick={() => handleSendMessage('all')} style={{ width: '60px', height: '60px', borderRadius: '50%', border: 'none', backgroundColor: '#333', color: '#fff', fontSize: '20px', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', boxShadow: '0 4px 15px rgba(0,0,0,0.2)' }}>
                                ➤
                            </button>
                        </div>
                    </div>
                ) : (
                    <div style={{ flex: 1, display: 'flex', gap: '25px', minHeight: 0 }}>
                        {/* Selector Phòng */}
                        <div style={{ width: '280px', display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '10px', alignContent: 'flex-start', overflowY: 'auto', paddingRight: '10px', background: 'rgba(0,0,0,0.2)', padding: '20px', borderRadius: '25px' }} className="custom-scrollbar">
                            {allRooms.map(room => (
                                <div key={room} onClick={() => toggleRoom(room)} style={{ background: selectedRooms.includes(room) ? '#8b5e5e' : '#fff', color: selectedRooms.includes(room) ? '#fff' : '#333', padding: '12px 0', borderRadius: '15px', textAlign: 'center', fontSize: '14px', fontWeight: 'bold', cursor: 'pointer', transition: '0.2s', boxShadow: '0 3px 6px rgba(0,0,0,0.1)' }}>
                                    {room}
                                </div>
                            ))}
                        </div>

                        {/* Chat Riêng */}
                        <div style={{ flex: 1, display: 'flex', flexDirection: 'column', backgroundColor: 'rgba(255,255,255,0.05)', borderRadius: '30px', border: '1px solid rgba(255,255,255,0.2)', padding: '25px', minHeight: 0 }}>
                            <div style={{ flex: 1, overflowY: 'auto', paddingRight: '10px' }} className="custom-scrollbar">
                                <div style={{ color: '#fff', fontSize: '16px', marginBottom: '20px', padding: '12px 20px', background: 'rgba(0,0,0,0.4)', borderRadius: '15px', border: '1px solid rgba(255,255,255,0.1)' }}>
                                    👥 <strong>Gửi đến:</strong> {selectedRooms.length > 0 ? selectedRooms.join(', ') : 'Vui lòng chọn phòng...'}
                                </div>
                                {renderMessageList('private')}
                                <div ref={chatEndRef} />
                            </div>

                            <div style={{ display: 'flex', gap: '15px', marginTop: '20px', flexShrink: 0 }}>
                                <input style={{ flex: 1, padding: '18px 25px', borderRadius: '30px', border: 'none', outline: 'none', fontSize: '16px', backgroundColor: 'rgba(255,255,255,1)' }} placeholder="Nhập tin nhắn riêng..." value={message} onChange={(e) => setMessage(e.target.value)} onKeyPress={(e) => e.key === 'Enter' && canSendPrivate && handleSendMessage('private')} />
                                <button disabled={!canSendPrivate} onClick={() => handleSendMessage('private')} style={{ padding: '0 30px', borderRadius: '30px', border: 'none', backgroundColor: '#8b5e5e', color: '#fff', fontSize: '16px', fontWeight: 'bold', opacity: canSendPrivate ? 1 : 0.4, cursor: canSendPrivate ? 'pointer' : 'not-allowed', transition: '0.3s', boxShadow: '0 4px 15px rgba(0,0,0,0.2)' }}>Gửi</button>
                            </div>
                        </div>
                    </div>
                )}
            </div>
            <style>{`
                .custom-scrollbar::-webkit-scrollbar { width: 6px; }
                .custom-scrollbar::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.3); border-radius: 10px; }
                .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
            `}</style>
        </div>
    );
};

export default NhanTin;
